"use client";
// @zeus-internal
import { motion, useReducedMotion, type Variants } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { NumberTicker } from "./07-outcome-index/number-ticker";
const HEADER_VIEWPORT = { once: true, margin: "0px 0px -80px 0px" } as const;
const ARTICLE_VIEWPORT = { once: true, margin: "0px 0px -60px 0px" } as const;
const RULE_VIEWPORT = { once: true, margin: "-60px" } as const;
const REVEAL_S = 0.65;
const RULE_S = 0.8;
const STAGGER_S = 0.08;
const HEADER_HIDDEN = { opacity: 0, filter: "blur(8px)", y: 18 };
const HEADER_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
const ARTICLE: Variants = {
    hidden: { opacity: 0, y: 22 },
    shown: (i: number) => ({ opacity: 1, y: 0, transition: { duration: REVEAL_S, delay: i * STAGGER_S, ease: ARTEMIS_EASE_OUT } }),
};
const RULE: Variants = {
    hidden: { scaleX: 0 },
    shown: (i: number) => ({ scaleX: 1, transition: { duration: RULE_S, delay: i * STAGGER_S, ease: ARTEMIS_EASE_OUT } }),
};
const OUTCOMES = [
    {
        index: "01",
        value: "72",
        suffix: "%",
        title: "Fewer manual handoffs",
        body: "Routine approvals move forward without another meeting or status check.",
        note: "Across the last 90 days",
    },
    {
        index: "02",
        value: "3.4",
        suffix: "\u00D7",
        title: "More launches per quarter",
        body: "A shared operating rhythm keeps good work moving from decision to delivery.",
        note: "Compared with last year",
    },
    {
        index: "03",
        value: "84",
        suffix: "h",
        title: "Returned to every team",
        body: "Less coordination overhead gives each team more time for focused work.",
        note: "Average monthly savings",
    },
];
export default function StatsOutcomeIndex() {
    const reduce = useReducedMotion();
    return (<>
      <div className="art:w-full">
        <section className="art:w-full art:text-foreground">
          <div className="art:mx-auto art:w-full art:max-w-6xl">
            <motion.header className="art:grid art:gap-6 art:@min-[768px]/artemis:grid-cols-[1.2fr_0.8fr] art:@min-[768px]/artemis:items-end" initial={HEADER_HIDDEN} whileInView={reduce ? undefined : HEADER_SHOWN} viewport={HEADER_VIEWPORT} transition={{ duration: REVEAL_S, ease: ARTEMIS_EASE_OUT }}>
              <div className="art:max-w-2xl">
                <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest">
                  {"Operational outcomes"}
                </p>
                <h2 className="art:mt-5 art:whitespace-pre-line art:text-balance art:font-medium art:text-4xl art:leading-tight art:tracking-tight">
                  {"Results that change\nthe rhythm of work."}
                </h2>
              </div>
              <p className="art:max-w-md art:text-pretty art:text-muted-foreground art:leading-7 art:@min-[768px]/artemis:justify-self-end">
                {"Three measures that show what happens when momentum becomes part of the system."}
              </p>
            </motion.header>
            <div className="art:mt-14 art:border-border art:border-b">
              {OUTCOMES.map((item, i) => (<motion.article key={item.index} className="art:relative art:grid art:gap-8 art:py-10 art:@min-[640px]/artemis:py-12 art:@min-[768px]/artemis:min-h-64 art:@min-[768px]/artemis:grid-cols-[4rem_minmax(13rem,0.75fr)_1fr] art:@min-[768px]/artemis:items-center art:@min-[768px]/artemis:gap-10" custom={i} variants={ARTICLE} initial="hidden" whileInView={reduce ? undefined : "shown"} viewport={ARTICLE_VIEWPORT}>
                  <motion.span aria-hidden="true" className="art:absolute art:inset-x-0 art:top-0 art:h-px art:origin-left art:bg-border" custom={i} variants={RULE} initial="hidden" whileInView={reduce ? undefined : "shown"} viewport={RULE_VIEWPORT}/>
                  <div>
                    <p className="art:flex art:size-10 art:items-center art:justify-center art:rounded-full art:bg-muted art:font-mono art:text-muted-foreground art:text-xs art:tabular-nums">
                      {item.index}
                    </p>
                  </div>
                  <p className="art:font-medium art:text-6xl art:tabular-nums art:tracking-tighter art:@min-[640px]/artemis:text-7xl art:@min-[768px]/artemis:text-8xl">
                    <NumberTicker text={item.value} suffix={item.suffix}/>
                  </p>
                  <div className="art:max-w-2xl">
                    <h3 className="art:text-balance art:font-medium art:text-xl art:tracking-tight">{item.title}</h3>
                    <p className="art:mt-3 art:max-w-lg art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">{item.body}</p>
                    <div className="art:mt-6 art:flex art:items-center art:gap-3">
                      <span aria-hidden="true" className="art:h-px art:w-8 art:bg-border"/>
                      <p className="art:font-mono art:text-muted-foreground art:text-xs">{item.note}</p>
                    </div>
                  </div>
                </motion.article>))}
            </div>
          </div>
        </section>
      </div>
    </>);
}

"use client";
// @zeus-internal
import { ArtemisRollingNumber } from "../../../../lib/rolling-number";
export interface NumberTickerProps { text: string; className?: string; duration?: number; stagger?: number; prefix?: string; suffix?: string; label?: string; entrance?: boolean; }
export function NumberTicker({ text, className, duration = 0.9, stagger = 0.04, prefix, suffix, label }: NumberTickerProps) { return <ArtemisRollingNumber text={text} className={className} duration={duration} stagger={stagger} prefix={prefix} suffix={suffix} label={label} activation={"in-view"} amount={0.6}/>; }

"use client";
// @zeus-internal
import { animate, motion, useInView, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import { ARTEMIS_EASE_OUT } from "./ease";
export interface ArtemisRollingNumberProps {
  text: string;
  duration?: number;
  stagger?: number;
  className?: string;
  reducedMotion?: boolean;
  blur?: boolean;
  activation?: "in-view" | "immediate" | "mount";
  amount?: number;
  prefix?: string;
  suffix?: string;
  label?: string;
  blurUpdatesOnly?: boolean;
  staggerDigitsOnly?: boolean;
}
function Wheel({ value, delay, duration, reduced, blur, fromZero, blurUpdatesOnly }: { value: string; delay: number; duration: number; reduced: boolean; blur: boolean; fromZero: boolean; blurUpdatesOnly: boolean }) {
  const rail = useRef<HTMLSpanElement>(null);
  const firstPaint = useRef(true);
  useEffect(() => {
    const initial = firstPaint.current;
    firstPaint.current = false;
    if (!rail.current) return;
    if (!blur || reduced || value === "0" && !blurUpdatesOnly) { rail.current.style.filter = "none"; return; }
    if (blurUpdatesOnly && initial) return;
    const playback = animate(rail.current, { filter: ["blur(10px)", "blur(0px)"] }, { duration: 0.32, delay, ease: ARTEMIS_EASE_OUT });
    return () => playback.stop();
  }, [value, blur, reduced, blurUpdatesOnly]);
  return <span className="art:relative art:inline-block" style={{ clipPath: "inset(0)", lineHeight: "1.1em", height: "1.1em", width: "1ch", textAlign: "center" }}>
    <span className="art:invisible">{value}</span>
    <motion.span ref={rail} className="art:absolute art:inset-x-0 art:top-0 art:flex art:flex-col art:items-center art:will-change-[transform,filter]" initial={fromZero && !reduced ? { y: 0 } : false} animate={{ y: `${-Number(value) * 11 / 10}em` }} transition={reduced ? { duration: 0 } : { duration, delay, ease: ARTEMIS_EASE_OUT }}>
      {Array.from({ length: 10 }, (_, digit) => <span key={digit} className="art:flex art:items-center art:justify-center art:leading-none" style={{ height: "1.1em" }}>{digit}</span>)}
    </motion.span>
  </span>;
}
export function ArtemisRollingNumber({ text, duration = 0.6, stagger = 0.02, className = "", reducedMotion, blur = false, activation = "in-view", amount = 0.6, prefix = "", suffix = "", label, blurUpdatesOnly = false, staggerDigitsOnly = false }: ArtemisRollingNumberProps) {
  const anchor = useRef<HTMLSpanElement>(null);
  const observed = useInView(anchor, { once: true, amount });
  const visible = activation !== "in-view" || observed;
  const preference = useReducedMotion() === true;
  const reduced = reducedMotion ?? preference;
  const [settled, setSettled] = useState(false);
  const firstText = useRef(text), changedSinceMount = useRef(false);
  if (text !== firstText.current) changedSinceMount.current = true;
  useEffect(() => {
    if (!visible || settled) return;
    const timer = setTimeout(() => setSettled(true), (duration + text.length * stagger) * 1000);
    return () => clearTimeout(timer);
  }, [visible, settled, duration, stagger, text.length]);
  return <span ref={anchor} className={`art:inline-flex art:items-baseline art:tabular-nums ${className}`}>
    <span className="art:sr-only">{label ?? prefix + text + suffix}</span>
    <span aria-hidden="true" className="art:inline-flex art:items-baseline">{prefix && <span>{prefix}</span>}{Array.from(text, (char, index) => /[0-9]/.test(char)
      ? <Wheel key={text.length - index} value={visible || reduced ? char : "0"} delay={settled || reduced || activation === "mount" && changedSinceMount.current ? 0 : (staggerDigitsOnly ? text.slice(0, index).replace(/\D/g, "").length : index) * stagger} duration={duration} reduced={reduced} blur={blur} fromZero={activation === "mount"} blurUpdatesOnly={blurUpdatesOnly}/>
      : <span key={text.length - index}>{char}</span>)}{suffix && <span>{suffix}</span>}</span>
  </span>;
}
